draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // dog body
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // dog legs
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - 20 + Math.cos(t * 2) * 10, H/2 + 50);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + 20 + Math.cos(t * 2 + Math.PI) * 10, H/2 + 50);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - 20 + Math.cos(t * 2 + Math.PI * 2) * 10, H/2 + 70);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + 20 + Math.cos(t * 2 + Math.PI * 3) * 10, H/2 + 70);
  ctx.stroke();

  ctx.restore();
}
